static void CheckSigning(TouchIDDiagResult *result) {
  SecCodeRef code = NULL;
  if (SecCodeCopySelf(kSecCSDefaultFlags, &code) != errSecSuccess) {
    return;
  }

  result->has_signature =
      SecCodeCheckValidity(code, kSecCSDefaultFlags, NULL) == errSecSuccess;

  CFDictionaryRef signingInfo = NULL;
  if (SecCodeCopySigningInformation(code, kSecCSSigningInformation,
                                    &signingInfo) == errSecSuccess &&
      signingInfo != NULL) {
    CFDictionaryRef entitlements =
        CFDictionaryGetValue(signingInfo, kSecCodeInfoEntitlementsDict);
    if (entitlements != NULL &&
        CFGetTypeID(entitlements) == CFDictionaryGetTypeID()) {
      CFTypeRef appID = CFDictionaryGetValue(
          entitlements, CFSTR("com.apple.application-identifier"));
      CFTypeRef groups =
          CFDictionaryGetValue(entitlements, CFSTR("keychain-access-groups"));
      result->has_entitlements =
          appID != NULL && CFGetTypeID(appID) == CFStringGetTypeID() &&
          CFStringGetLength(appID) > 0 && groups != NULL &&
          CFGetTypeID(groups) == CFArrayGetTypeID() &&
          CFArrayGetCount(groups) > 0;
    }
    CFRelease(signingInfo);
  }
  CFRelease(code);
}

static int CheckSecureEnclave(void) {
  CFErrorRef error = NULL;
  SecAccessControlRef access = SecAccessControlCreateWithFlags(
      kCFAllocatorDefault, kSecAttrAccessibleWhenUnlockedThisDeviceOnly,
      kSecAccessControlPrivateKeyUsage | kSecAccessControlBiometryAny, &error);
  if (access == NULL) {
    if (error != NULL) {
      CFRelease(error);
    }
    return 0;
  }

  NSData *tag = [[[NSUUID UUID] UUIDString] dataUsingEncoding:NSUTF8StringEncoding];
  NSDictionary *attributes = @{
    (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
    (id)kSecAttrKeySizeInBits : @256,
    (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
    (id)kSecPrivateKeyAttrs : @{
      (id)kSecAttrIsPermanent : @YES,
      (id)kSecAttrAccessControl : (__bridge id)access,
      (id)kSecAttrApplicationTag : tag,
    },
  };
  SecKeyRef key =
      SecKeyCreateRandomKey((__bridge CFDictionaryRef)attributes, &error);
  if (error != NULL) {
    CFRelease(error);
  }
  CFRelease(access);
  if (key == NULL) {
    return 0;
  }
  CFRelease(key);

  NSDictionary *query = @{
    (id)kSecClass : (id)kSecClassKey,
    (id)kSecAttrKeyType : (id)kSecAttrKeyTypeECSECPrimeRandom,
    (id)kSecAttrTokenID : (id)kSecAttrTokenIDSecureEnclave,
    (id)kSecAttrApplicationTag : tag,
  };
  return SecItemDelete((__bridge CFDictionaryRef)query) == errSecSuccess;
}

TouchIDDiagResult TouchIDDiag(void) {
  TouchIDDiagResult result = {0};
  @autoreleasepool {
    CheckSigning(&result);

    LAContext *context = [[LAContext alloc] init];
    result.passed_la_policy_test =
        [context canEvaluatePolicy:LAPolicyDeviceOwnerAuthenticationWithBiometrics
                            error:NULL];
    result.passed_secure_enclave_test = CheckSecureEnclave();
  }
  return result;
}
